function isOtherDegree(deg) {
  if (!deg) return false;
  const d = String(deg).trim().toLowerCase();
  return d.startsWith('other') || d.includes('other degree') || d.includes('other hospitality');
}
window.isOtherDegree = isOtherDegree;

